mapper.select:
select ifnull(max(sort_id), 0) + 1
from chat_base
where chat_business_id = #{chatBusinessId}
  and created_by = #{createdBy}
  and is_active = 1

select cb.chat_id as chatId, cb.chat_name as chatName, cb.chat_business_type as chatBusinessType, cb.chat_business_id as chatBusinessId, cb.bound_view_id as boundViewId, cb.last_chat_message_id as lastChatMessageId, case when fav.fav_id is null then false else true end as isFavorite, fav.fav_id as favId, fav.fav_sort_id as favSortId, cb.created_time as createdTime, cb.updated_time as updatedTime from chat_base cb left join ssm_ai_analysis_fav fav on cast(cb.chat_id as char) = fav.chat_id and fav.created_by = #{userName} where cb.created_by = #{userName} and cb.is_active = 1
and cb.chat_business_type = #{chatBusinessType}
and cb.chat_business_id = #{chatBusinessId}
and cb.bound_view_id = #{boundViewId}
and fav.fav_id is not null
order by case when fav.fav_id is null then 1 else 0 end asc, fav.fav_sort_id asc, cb.sort_id desc, cb.updated_time desc limit #{offset}, #{pageSize}

select count(1)
from chat_base cb
left join ssm_ai_analysis_fav fav
    on cast(cb.chat_id as char) = fav.chat_id
    and fav.created_by = #{userName}
where
    cb.created_by = #{userName}
    and cb.is_active = 1

        and cb.chat_business_type = #{chatBusinessType}


        and cb.chat_business_id = #{chatBusinessId}


        and fav.fav_id is not null
